changeSet.sql:
UPDATE place SET needs = 'adventure' WHERE kind = 'ATTRACTION' AND needs IS NULL;
UPDATE place SET needs = 'enjoy'
WHERE kind = 'ATTRACTION'
  AND (LOWER(name) LIKE '%ruộng%' OR LOWER(name) LIKE '%thác%'
    OR LOWER(name) LIKE '%suối%' OR LOWER(name) LIKE '%hồ%'
    OR LOWER(name) LIKE '%đồi%' OR LOWER(name) LIKE '%thung lũng%');
